from pydantic import BaseModel, Field, ValidationError
import anthropic

class UserProfileExtraction(BaseModel):
    user_id: str = Field(description="UUID string")
    roles: list[str] = Field(min_length=1)
    is_active: bool
    quota_limit: int = Field(gt=0)

def extract_structured_data(raw_text: str, client: anthropic.Anthropic) -> UserProfileExtraction:
    schema = UserProfileExtraction.model_json_schema()
    prompt = f"Extract information matching this schema exactly. Output ONLY valid JSON.\nSchema: {schema}\nData: {raw_text}"

    response = client.messages.create(
        model="claude-3-5-haiku-20241022",
        max_tokens=1024,
        messages=[{"role": "user", "content": prompt}]
    )

    try:
        return UserProfileExtraction.model_validate_json(response.content[0].text)
    except ValidationError as err:
        # Self-healing reflection loop
        repair_prompt = f"Your previous output failed validation:\n{err}\nCorrect the JSON and output only valid JSON."
        repaired = client.messages.create(
            model="claude-3-5-haiku-20241022",
            max_tokens=1024,
            messages=[
                {"role": "user", "content": prompt},
                {"role": "assistant", "content": response.content[0].text},
                {"role": "user", "content": repair_prompt}
            ]
        )
        return UserProfileExtraction.model_validate_json(repaired.content[0].text)

import asyncio
from typing import Any

async def dispatch_tool_call(tool_call: dict) -> dict:
 name, args, call_id = tool_call["name"], tool_call["input"], tool_call["id"]
 try:
 handler = TOOL_REGISTRY[name]
 result = await handler(**args)
 return {"type": "tool_result", "tool_use_id": call_id, "content": str(result)}
 except Exception as err:
 return {"type": "tool_result", "tool_use_id": call_id, "content": f"Error: {err}", "is_error": True}

async def execute_turn_tools_parallel(tool_calls: list[dict]) -> list[dict]:
 """Execute all tool calls concurrently using asyncio.gather."""
 tasks = [dispatch_tool_call(call) for call in tool_calls]
 return await asyncio.gather(*tasks)
